// === Tab: mySketch ===
// Basic shader setup by Adam Ferris
// https://github.com/aferriss/p5jsShaderExamples

// a shader variable
let theShader;

function setup() {
  pixelDensity(1);
  // shaders require WEBGL mode to work
  createCanvas(1112, 834, WEBGL);
	theShader = createShader(vert, frag);
  noStroke();
}

function draw() {  
  // send resolution of sketch into shader
  theShader.setUniform('u_resolution', [width, windowHeight]);
  theShader.setUniform('u_time', frameCount);

  // shader() sets the active shader with our shader
  shader(theShader);

  // rect gives us some geometry on the screen
  rect(0,0,windowWidth, height);
}

function windowResized(){
  resizeCanvas(windowWidth, windowHeight);
}

let vert = `
// Vert Shader by Adam Ferris
// https://github.com/aferriss/p5jsShaderExamples

attribute vec3 aPosition;

// Always include this to get the position of the pixel and map the shader correctly onto the shape

void main() {

  // Copy the position data into a vec4, adding 1.0 as the w parameter
  vec4 positionVec4 = vec4(aPosition, 1.0);

  // Scale to make the output fit the canvas
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0; 

  // Send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`


let frag = `
// Flames
// Werllen Castro, 2022
// github.com/werls

#ifdef GL_ES
precision highp float;
#endif

uniform vec2 u_resolution;
uniform float u_time;

#define TAU 6.283185307179586

vec3 colorA = vec3(0.0,0.0,0.5);
vec3 colorB = vec3(1.0,0.2,0.224);

// 2D Random (The Book of Shaders)
// https://thebookofshaders.com/10/
float random (in vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

// 2D Noise based on Morgan McGuire @morgan3d
// https://www.shadertoy.com/view/4dS3Wd
float noise (in vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    // Four corners in 2D of a tile
    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    // Smooth Interpolation

    // Cubic Hermine Curve.  Same as SmoothStep()
    vec2 u = f*f*(3.0-2.0*f);
    // u = smoothstep(0.,1.,f);

    // Mix 4 coorners percentages
    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
}

void main() {
  float mx = max(u_resolution.x, u_resolution.y);
  vec2 st = (gl_FragCoord.xy / u_resolution.xy) - 0.5;
  st /= .6;

  float circle = distance(st, vec2(0.5));
  vec3 color = vec3(circle); 
  color += st.y / .2 + st.x * noise(st / .2 - u_time / 10.0) * TAU;
  color = mix(colorB, colorA, color);

  gl_FragColor = vec4(color, 1.0);
}
`

